from fractions import Fraction
from itertools import combinations

money = {"gadwall": 11, "german_shepherd": 25, "wolf": 67}
diameter = Fraction(22)
box = tuple(map(Fraction, ("23.5", "28.7", "21.3")))

# A spherical basketball fits only if its diameter fits every box dimension.
fits = all(diameter <= side for side in box)
richer = money["wolf"] > money["gadwall"] + money["german_shepherd"]

facts = {"wolf_struggles_to_find_food"}
if fits:
    facts.add("basketball_fits")
if richer:
    facts.add("wolf_has_more_than_combined")

# No movie-watching, abundant-food, or zebra-dancing fact is given.
# Struggling to find food does not establish any of those antecedents.
rules = {
    "Rule1": ({"watching_movie_before_moon_landing"}, "not_hugs"),
    "Rule2": ({"basketball_fits"}, "hugs"),
    "Rule3": ({"abundant_food"}, "not_hugs"),
    "Rule4": ({"zebra_dances_with_walrus"}, "castle"),
    "Rule5": ({"wolf_has_more_than_combined"}, "hugs"),
    # The wolf hugging the fish establishes that at least one animal does.
    "Rule6": ({"hugs"}, "not_castle"),
}
preferred = {
    ("Rule1", "Rule2"), ("Rule1", "Rule5"),
    ("Rule3", "Rule2"), ("Rule3", "Rule5"),
    ("Rule4", "Rule6"),
}
opposite = {
    "hugs": "not_hugs", "not_hugs": "hugs",
    "castle": "not_castle", "not_castle": "castle",
}
literals = tuple(opposite)

# Exhaustively test every possible set of rule conclusions for support.
# All dependencies here are acyclic, so supported fixed points cannot
# manufacture conclusions through circular support.
models = []
for size in range(len(literals) + 1):
    for choice in combinations(literals, size):
        conclusions = set(choice)
        known = facts | conclusions
        applicable = {
            name for name, (antecedents, _) in rules.items()
            if antecedents <= known
        }
        supported = set()
        for name in applicable:
            conclusion = rules[name][1]
            opponents = {
                other for other in applicable
                if rules[other][1] == opposite[conclusion]
            }
            if all((name, other) in preferred for other in opponents):
                supported.add(conclusion)
        if supported == conclusions:
            models.append((conclusions, applicable))

print("Wolf money:", money["wolf"])
print("Other two animals' combined money:",
      money["gadwall"] + money["german_shepherd"])
print("Rule5 money antecedent:", richer)
print("Basketball fits box:", fits)
print("Supported fixed points:", len(models))

if len(models) != 1:
    print("UNSUPPORTED")
    print("CHECK UNKNOWN")
else:
    conclusions, applicable = models[0]
    print("Applicable rules:", ", ".join(sorted(applicable)))
    print("Conclusions:", ", ".join(sorted(conclusions)))

    if "castle" in conclusions and "not_castle" not in conclusions:
        expected = "proved"
    elif "not_castle" in conclusions and "castle" not in conclusions:
        expected = "disproved"
    elif "castle" not in conclusions and "not_castle" not in conclusions:
        expected = "unknown"
    else:
        expected = None

    submitted = "disproved"  # Submitted claim: the walrus does not create it.
    print("Expected result:", expected)
    if expected is None:
        print("UNSUPPORTED")
        print("CHECK UNKNOWN")
    else:
        print("CHECK PASS" if expected == submitted else "CHECK FAIL")
